/// <summary>
/// getAccuracyReport's request (supervisor only). FromDate / ToDate are ISO dates (yyyy-MM-dd),
/// inclusive. GroupBy: LOCATION, ITEM, ABC_CLASS or COUNTER.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountAccuracyRequest
{
    DataAreaId dataAreaId;
    str        userId;
    str        warehouseId;
    str        fromDate;
    str        toDate;
    str        groupBy;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('FromDate')]
public str parmFromDate(str _value = fromDate)
{
    fromDate = _value;
    return fromDate;
}

[DataMemberAttribute('ToDate')]
public str parmToDate(str _value = toDate)
{
    toDate = _value;
    return toDate;
}

[DataMemberAttribute('GroupBy')]
public str parmGroupBy(str _value = groupBy)
{
    groupBy = _value;
    return groupBy;
}
